+function sceneIndexFromFrame(startFrame, scenes, fps) {
+  let frameOffset = 0;
+  for (let s = 0; s < scenes.length; s++) {
+    const sceneDur = (scenes[s].duration || 5) * fps;
+    if (startFrame >= frameOffset && startFrame < frameOffset + sceneDur) {
+      return s;
+    }
+    frameOffset += sceneDur;
+  }
+  // Fallback: clamp to last scene if startFrame exceeds total duration
+  return Math.max(0, scenes.length - 1);
+}
